const coreProblems = [
  {id:1,title:'Two Sum',cat:'Arrays & Hashing',difficulty:'Easy',fn:'two_sum',prompt:'Given an array of integers <code>nums</code> and an integer <code>target</code>, return the indices of the two numbers that add up to <code>target</code>. You may assume exactly one valid answer exists.',examples:['Input: nums = [2,7,11,15], target = 9\nOutput: [0,1]','Input: nums = [3,2,4], target = 6\nOutput: [1,2]'],constraints:['2 ≤ nums.length ≤ 10⁴','Exactly one valid answer exists.'],hint:'As you scan left to right, what value would complete the current number? Store values you have already seen with their indices.',template:'def two_sum(nums, target):\n    # Return the two indices.\n    pass\n',tests:[[[2,7,11,15],9,[0,1]],[[3,2,4],6,[1,2]],[[3,3],6,[0,1]]]},
  {id:121,title:'Best Time to Buy and Sell Stock',cat:'Sliding Window',difficulty:'Easy',fn:'max_profit',prompt:'You may choose one day to buy one stock and a different future day to sell it. Return the maximum profit. If no profit is possible, return <code>0</code>.',examples:['Input: prices = [7,1,5,3,6,4]\nOutput: 5','Input: prices = [7,6,4,3,1]\nOutput: 0'],constraints:['1 ≤ prices.length ≤ 10⁵','0 ≤ prices[i] ≤ 10⁴'],hint:'A selling price only needs the lowest buy price that occurred before it. Maintain that value as you scan.',template:'def max_profit(prices):\n    # Return the best possible profit.\n    pass\n',tests:[[[7,1,5,3,6,4],5],[[7,6,4,3,1],0],[[2,4,1],2]]},
  {id:125,title:'Valid Palindrome',cat:'Two Pointers',difficulty:'Easy',fn:'is_palindrome',prompt:'A phrase is a palindrome if, after converting uppercase letters to lowercase and removing non-alphanumeric characters, it reads the same forward and backward. Return whether <code>s</code> is a palindrome.',examples:['Input: s = "A man, a plan, a canal: Panama"\nOutput: true','Input: s = "race a car"\nOutput: false'],constraints:['1 ≤ s.length ≤ 2 × 10⁵'],hint:'Use a pointer at each end. Skip characters that should not participate before comparing.',template:'def is_palindrome(s):\n    # Return True or False.\n    pass\n',tests:[['A man, a plan, a canal: Panama',true],['race a car',false],[' ',true]]},
  {id:20,title:'Valid Parentheses',cat:'Stack',difficulty:'Easy',fn:'is_valid',prompt:'Given a string containing only <code>()[]{}</code>, determine if the input string is valid. Open brackets must be closed by the same type and in the correct order.',examples:['Input: s = "()[]{}"\nOutput: true','Input: s = "(]"\nOutput: false'],constraints:['1 ≤ s.length ≤ 10⁴'],hint:'A closing bracket must match the most recently opened bracket that has not yet been closed.',template:'def is_valid(s):\n    # Return True or False.\n    pass\n',tests:[['()[]{}',true],['(]',false],['([)]',false],['{[]}',true]]},
  {id:217,title:'Contains Duplicate',cat:'Arrays & Hashing',difficulty:'Easy',fn:'contains_duplicate',prompt:'Given an integer array <code>nums</code>, return <code>true</code> if any value appears at least twice; otherwise return <code>false</code>.',examples:['Input: nums = [1,2,3,1]\nOutput: true','Input: nums = [1,2,3,4]\nOutput: false'],constraints:['1 ≤ nums.length ≤ 10⁵'],hint:'Ask whether you have already seen the current value.',template:'def contains_duplicate(nums):\n    # Return True or False.\n    pass\n',tests:[[[1,2,3,1],true],[[1,2,3,4],false],[[1,1,1,3,3,4,3,2,4,2],true]]},
  {id:242,title:'Valid Anagram',cat:'Arrays & Hashing',difficulty:'Easy',fn:'is_anagram',prompt:'Given two strings <code>s</code> and <code>t</code>, return <code>true</code> if <code>t</code> is an anagram of <code>s</code>, and <code>false</code> otherwise.',examples:['Input: s = "anagram", t = "nagaram"\nOutput: true','Input: s = "rat", t = "car"\nOutput: false'],constraints:['1 ≤ s.length, t.length ≤ 5 × 10⁴'],hint:'Two anagrams have the same character counts.',template:'def is_anagram(s, t):\n    # Return True or False.\n    pass\n',tests:[['anagram','nagaram',true],['rat','car',false],['aacc','ccac',false]]}
];
const curriculum = [
  ['Arrays & Hashing',['Group Anagrams','Top K Frequent Elements','Product of Array Except Self','Valid Sudoku','Longest Consecutive Sequence']],['Two Pointers',['Two Sum II','3Sum','Container With Most Water','Trapping Rain Water']],['Sliding Window',['Longest Substring Without Repeating Characters','Longest Repeating Character Replacement','Permutation in String','Minimum Window Substring','Minimum Size Subarray Sum']],['Stack',['Min Stack','Evaluate Reverse Polish Notation','Daily Temperatures','Car Fleet','Largest Rectangle in Histogram']],['Binary Search',['Binary Search','Search a 2D Matrix','Koko Eating Bananas','Find Minimum in Rotated Sorted Array','Search in Rotated Sorted Array']],['Linked Lists',['Reverse Linked List','Merge Two Sorted Lists','Linked List Cycle','Remove Nth Node From End','Reorder List']],['Trees',['Invert Binary Tree','Maximum Depth of Binary Tree','Diameter of Binary Tree','Balanced Binary Tree','Same Tree','Subtree of Another Tree','Lowest Common Ancestor of a BST','Binary Tree Right Side View','Validate BST','Kth Smallest in a BST','Construct Tree from Preorder and Inorder']],['Heaps',['Kth Largest Element in a Stream','Last Stone Weight','K Closest Points to Origin','Task Scheduler','Design Twitter']],['Graphs',['Number of Islands','Clone Graph','Course Schedule','Pacific Atlantic Water Flow','Word Ladder']],['Backtracking',['Subsets','Combination Sum','Permutations','Word Search','N-Queens']],['Dynamic Programming',['Climbing Stairs','House Robber','Coin Change','Longest Increasing Subsequence','Word Break']],['Intervals & Greedy',['Merge Intervals','Insert Interval','Non-overlapping Intervals','Jump Game','Gas Station']]
];
const allProblems=[...coreProblems,...curriculum.flatMap(([cat,titles])=>titles.map((title,i)=>({id:`${cat}-${i}`,title,cat,difficulty:cat==='Trees'||cat==='Graphs'||cat==='Dynamic Programming'?'Medium':'Medium',comingSoon:true})) )];
let current=coreProblems[0],pyodide=null,loadingPyodide=null;const completed=new Set(JSON.parse(localStorage.getItem('ir-completed')||'[]'));
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function renderList(filter=''){const list=$('#problemList');list.innerHTML='';const groups={};allProblems.filter(p=>p.title.toLowerCase().includes(filter.toLowerCase())).forEach(p=>(groups[p.cat]??=[]).push(p));Object.entries(groups).forEach(([cat,items])=>{const heading=document.createElement('div');heading.className='category-heading';heading.textContent=cat;list.append(heading);items.forEach(p=>{const b=document.querySelector('#problemItemTemplate').content.firstElementChild.cloneNode(true);b.classList.toggle('selected',p.id===current.id);b.querySelector('.status-dot').classList.toggle('done',completed.has(String(p.id)));b.querySelector('.item-number').textContent=p.comingSoon?'•':p.id;b.querySelector('.item-title').textContent=p.title;b.onclick=()=>selectProblem(p);list.append(b)})})}
function selectProblem(problem){if(problem.comingSoon){$('#consoleOutput').textContent='This curriculum problem is queued for the full test-suite release. Start with the runnable foundations or add it to your path.';return}current=problem;$('#problemNumber').textContent=`${problem.id}.`;$(' #difficulty'.replace(' ',''));const diff=$('#difficulty');diff.textContent=problem.difficulty;diff.className=`difficulty ${problem.difficulty.toLowerCase()}`;$('#topic').textContent=problem.cat;$('#problemStatement').innerHTML=`<h1>${problem.title}</h1><p>${problem.prompt}</p>`;$('#examples').innerHTML=problem.examples.map((e,i)=>`<div class="example">Example ${i+1}\n${esc(e)}</div>`).join('');$('#constraints').innerHTML=problem.constraints.map(c=>`<li>${esc(c)}</li>`).join('');$('#hint').textContent=problem.hint;$('#codeEditor').value=problem.template;updateLines();$('#console').className='console';$('#consoleOutput').textContent='Write your solution, then Run to test it against the visible cases.';renderList($('#problemSearch').value)}
function updateLines(){const n=$('#codeEditor').value.split('\n').length;$('#lineNumbers').innerHTML=Array.from({length:n},(_,i)=>`<span>${i+1}</span>`).join('')}
function json(v){return JSON.stringify(v)}
async function ensurePython(){if(pyodide)return pyodide;if(loadingPyodide)return loadingPyodide;$('#runtimeStatus').textContent='Loading Python runtime…';loadingPyodide=loadPyodide({indexURL:'https://cdn.jsdelivr.net/pyodide/v0.27.0/full/'}).then(p=>{pyodide=p;$('#runtimeStatus').textContent='Python runner ready';return p}).catch(e=>{loadingPyodide=null;$('#runtimeStatus').textContent='Runner unavailable';throw e});return loadingPyodide}
function pythonHarness(){const tests=JSON.stringify(JSON.stringify(current.tests));return `\nimport json\nTESTS = json.loads(${tests})\ndef _norm(x):\n    if isinstance(x, tuple): return list(x)\n    return x\npassed = 0\nfor i, test in enumerate(TESTS, 1):\n    *args, expected = test\n    try:\n        actual = _norm(${current.fn}(*args))\n        if actual == expected:\n            passed += 1\n            print(f\"✓ Test {i}: passed\")\n        else:\n            print(f\"✗ Test {i}: expected {expected!r}, got {actual!r}\")\n    except Exception as e:\n        print(f\"✗ Test {i}: {type(e).__name__}: {e}\")\nprint(f\"RESULT: {passed}/{len(TESTS)} tests passed\")\n`;}
async function run(submit=false){const output=$('#consoleOutput'),box=$('#console');box.className='console';output.textContent='Running…';try{const py=await ensurePython();let text='';py.setStdout({batched:s=>text+=s+'\n'});await py.runPythonAsync($('#codeEditor').value+pythonHarness());output.textContent=text.trim();const pass=`RESULT: ${current.tests.length}/${current.tests.length}`;box.classList.add(text.includes(pass)?'success':'failure');if(submit&&text.includes(pass)){completed.add(String(current.id));localStorage.setItem('ir-completed',JSON.stringify([...completed]));updateProgress();renderList($('#problemSearch').value);output.textContent+='\n\nSubmitted successfully — marked mastered.'}}catch(e){box.classList.add('failure');output.textContent=`Runner error: ${e.message||e}`}}
function updateProgress(){const total=42,done=completed.size;$('#progressText').textContent=`${done} / ${total} complete`;$('#progressBar').style.width=`${Math.min(100,done/total*100)}%`;$('#solvedCount').textContent=done;$('#yellowCount').textContent=Math.max(0,3-done);$('#nextReview').textContent=done?'2 days':'—'}
function renderPath(){const steps=[['Weeks 1–2','Foundations','Arrays, hash maps, two pointers, sliding window, and stacks. Three sessions each week.'],['Weeks 3–4','Control flow','Binary search, linked lists, trees, and heaps. Focus on bugs you can explain.'],['Weeks 5–6','Expansion','Graphs, backtracking, intervals, greedy, and 1-D dynamic programming.'],['Weeks 7–8','Interview mode','Mixed mediums and one timed practice set each week.']];$('#pathGrid').innerHTML=steps.map(([time,title,body])=>`<article class="path-card"><p class="eyebrow">${time}</p><h3>${title}</h3><p>${body}</p></article>`).join('')}
document.addEventListener('DOMContentLoaded',()=>{renderList();selectProblem(current);renderPath();updateProgress();$('#problemSearch').addEventListener('input',e=>renderList(e.target.value));$('#codeEditor').addEventListener('input',updateLines);$('#runButton').onclick=()=>run();$('#submitButton').onclick=()=>run(true);$('#resetButton').onclick=()=>{ $('#codeEditor').value=current.template;updateLines()};document.querySelectorAll('.nav-link').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav-link').forEach(x=>x.classList.remove('active'));b.classList.add('active');const v=b.dataset.view;$('#practice-view').classList.toggle('hidden',v!=='practice');$('#path-view').classList.toggle('hidden',v!=='path');$('#progress-view').classList.toggle('hidden',v!=='progress')})});
